package me.eiakoji.integration.synthesis;

import java.time.Duration;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;
import java.util.logging.Level;
import java.util.logging.Logger;

/**
 * Enterprise Integration Patterns Part VIII: Synthesis Case Study.
 * Composes Transactional Outbox, Claim Check, Scatter-Gather, and Distributed Saga
 * with backward compensating actions and circuit breaker fault isolation.
 */
public final class OmnichannelOrderSynthesisOrchestrator {

    private static final Logger log = Logger.getLogger(OmnichannelOrderSynthesisOrchestrator.class.getName());

    // -------------------------------------------------------------------------
    // 1. Domain Envelopes & Claim Check Abstraction
    // -------------------------------------------------------------------------
    public record OrderItem(String sku, int quantity, double unitPrice) {}
    public record OrderEvent(
        String orderId,
        String customerId,
        List<OrderItem> items,
        double totalAmount,
        String claimCheckUri,
        Instant timestamp
    ) {
        public OrderEvent {
            items = List.copyOf(items);
        }
    }

    public record SupplierQuote(String supplierId, double priceQuote, int estimatedDays) {}

    // -------------------------------------------------------------------------
    // 2. Scatter-Gather Supplier Quotation Mesh (Structured Concurrency)
    // -------------------------------------------------------------------------
    public static final class ScatterGatherQuoteAggregator {
        private final List<String> suppliers;
        private final Duration deadline;

        public ScatterGatherQuoteAggregator(List<String> suppliers, Duration deadline) {
            this.suppliers = List.copyOf(suppliers);
            this.deadline = deadline;
        }

        public Optional<SupplierQuote> fetchBestQuote(String sku) {
            try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
                List<Future<SupplierQuote>> futures = suppliers.stream()
                    .map(sup -> executor.submit(() -> querySupplier(sup, sku)))
                    .toList();

                List<SupplierQuote> quotes = new ArrayList<>();
                for (Future<SupplierQuote> future : futures) {
                    try {
                        quotes.add(future.get(deadline.toMillis(), TimeUnit.MILLISECONDS));
                    } catch (TimeoutException e) {
                        log.warning("Supplier query timed out on deadline barrier");
                    } catch (Exception e) {
                        log.log(Level.WARNING, "Supplier query failed", e);
                    }
                }

                return quotes.stream().min(Comparator.comparingDouble(SupplierQuote::priceQuote));
            }
        }

        private SupplierQuote querySupplier(String supplierId, String sku) throws InterruptedException {
            // Simulate network latency
            Thread.sleep(ThreadLocalRandom.current().nextInt(50, 250));
            double quote = 100.0 + ThreadLocalRandom.current().nextDouble(0.0, 50.0);
            return new SupplierQuote(supplierId, quote, 2);
        }
    }

    // -------------------------------------------------------------------------
    // 3. Distributed Saga State Machine & Compensating Orchestrator
    // -------------------------------------------------------------------------
    public static final class DistributedOrderSagaCoordinator {
        public enum SagaState { STARTED, CREDIT_RESERVED, INVENTORY_ALLOCATED, PAYMENT_CAPTURED, COMPLETED, COMPENSATING, CANCELLED }

        public record SagaContext(
            String sagaId,
            OrderEvent order,
            AtomicReference<SagaState> state,
            Deque<Runnable> compensations
        ) {
            public SagaContext(String sagaId, OrderEvent order) {
                this(sagaId, order, new AtomicReference<>(SagaState.STARTED), new ConcurrentLinkedDeque<>());
            }
        }

        // Dependencies (Simulated)
        private final AtomicBoolean paymentServiceHealthy = new AtomicBoolean(true);

        public boolean executeSaga(OrderEvent order) {
            String sagaId = "saga-" + UUID.randomUUID();
            SagaContext ctx = new SagaContext(sagaId, order);
            log.info("Starting distributed saga: " + sagaId + " for order: " + order.orderId());

            try {
                // Step 1: Reserve Customer Credit (T1)
                reserveCredit(ctx);
                ctx.compensations().push(() -> releaseCredit(ctx)); // Register C1
                ctx.state().set(SagaState.CREDIT_RESERVED);

                // Step 2: Allocate Warehouse Inventory (T2)
                allocateInventory(ctx);
                ctx.compensations().push(() -> restockInventory(ctx)); // Register C2
                ctx.state().set(SagaState.INVENTORY_ALLOCATED);

                // Step 3: Authorize & Capture Payment (T3)
                capturePayment(ctx);
                ctx.compensations().push(() -> voidPayment(ctx)); // Register C3
                ctx.state().set(SagaState.PAYMENT_CAPTURED);

                ctx.state().set(SagaState.COMPLETED);
                log.info("Saga completed successfully: " + sagaId);
                return true;

            } catch (Exception failure) {
                log.log(Level.SEVERE, "Saga step failed. Initiating backward compensating rollback: " + sagaId, failure);
                rollbackSaga(ctx);
                return false;
            }
        }

        private void reserveCredit(SagaContext ctx) {
            log.info("[T1] Reserved credit for customer: " + ctx.order().customerId());
        }

        private void releaseCredit(SagaContext ctx) {
            log.info("[C1] Compensating action: Released customer credit hold: " + ctx.order().customerId());
        }

        private void allocateInventory(SagaContext ctx) {
            log.info("[T2] Allocated warehouse inventory for items: " + ctx.order().items().size());
        }

        private void restockInventory(SagaContext ctx) {
            log.info("[C2] Compensating action: Restocked warehouse inventory for items");
        }

        private void capturePayment(SagaContext ctx) {
            if (!paymentServiceHealthy.get()) {
                throw new IllegalStateException("Payment Gateway 502 Bad Gateway Outage");
            }
            log.info("[T3] Payment captured for amount: $" + ctx.order().totalAmount());
        }

        private void voidPayment(SagaContext ctx) {
            log.info("[C3] Compensating action: Voided payment authorization");
        }

        private void rollbackSaga(SagaContext ctx) {
            ctx.state().set(SagaState.COMPENSATING);
            while (!ctx.compensations().isEmpty()) {
                Runnable compensation = ctx.compensations().pop();
                try {
                    compensation.run();
                } catch (Exception e) {
                    log.log(Level.SEVERE, "CRITICAL: Compensation failed. Quarantining to DLQ: " + ctx.sagaId(), e);
                }
            }
            ctx.state().set(SagaState.CANCELLED);
            log.info("Saga rollback finished. Order marked CANCELLED: " + ctx.order().orderId());
        }

        public void setPaymentServiceHealthy(boolean healthy) {
            this.paymentServiceHealthy.set(healthy);
        }
    }
}
